# Words 901-950 (prepositions PRP-031..070, conjunctions CNJ-001..010)
Q = "(preposition — no other forms)"
C = "(conjunction — no other forms)"
R = [
("PRP-031",Q,"Use 'out of' before a noun, not 'out from'.","OUT OF: moving from inside to outside.","'Out of order' = not working. 'Out of stock' = none left.","Write a sentence about getting out of a bus or car.",None,"out of vs outside","Out of = movement from inside (walk out of the room). Outside = position (wait outside the room)."),
("PRP-032",Q,"'Outside' is enough; 'of' is usually dropped in standard English.","OUTSIDE = OUT + SIDE.","'Outside of work' (US, informal) = apart from work.","Write a sentence about what is outside your window.",None,"outside vs out","Outside + noun (outside the house). Out alone or 'out of' (go out, out of the house)."),
("PRP-033",Q,"'Over' already means 'more than', so 'more than over' repeats it.","OVER = above, or more than.","'Over the phone' = by phone. 'It's over' = finished.","Write a sentence using 'over' to mean 'more than'.",None,"over vs above","Over = higher, covering, or across. Above = higher than, not touching."),
("PRP-034",Q,"To tell time, use 'half past' + hour: 'half past six'.","PAST = after the hour.","Indian English 'six and a half' is understood, but 'half past six' is standard.","Write the time 7:30 and 8:15 in words.",None,"past vs passed","Past = preposition/time (half past six). Passed = verb (I passed the exam)."),
("PRP-035",Q,"Use 'through' for going in one side and out the other.","THROUGH = in one side, out the other, like a tunnel.","'Through' is often misspelt: 'thru' is only informal American.","Write a sentence about walking through a market.",None,"through vs across","Through = inside something (through a tunnel). Across = over a surface (across a road)."),
("PRP-036",Q,"'Throughout' already means 'the whole', so 'the whole' repeats it.","THROUGH + OUT = from start to end.","'Throughout the year' = all year.","Write a sentence about something that happens throughout the year.",None,"throughout vs through","Through = from one side to the other. Throughout = in every part, or for the whole time.","It rained throughout the whole day.","It rained throughout the day."),
("PRP-037",Q,"'Till' takes its object directly; 'from' is not needed.","TILL = until, informal.","'Till' is not short for 'until'; it's an old word. ''Til' is informal.","Write a sentence using 'till'.",None,"till vs until","Same meaning. Until is slightly more formal."),
("PRP-038",Q,"'Home' doesn't take 'to' when it means your own home.","GO HOME, COME HOME — no 'to'.","Also: 'go abroad', 'go upstairs', 'go there' — no 'to'.","Write a sentence about when you go home.",None,"go home vs go to home","Go home (correct). 'Go to home' is wrong. But 'go to my friend's home' is fine."),
("PRP-039",Q,"'Toward' takes its object directly; 'of' is not needed.","TO + WARD: in the direction of.","US prefers 'toward'; UK prefers 'towards'.","Write a sentence about walking toward a friend.",None,"toward vs towards","Same meaning. Toward (US), towards (UK and India)."),
("PRP-040",Q,"'Towards' takes its object directly; an extra 'to' is not needed.","TOWARDS = in the direction of, or for.","'Save towards a car' = save money for a car.","Write a sentence about money you save towards something.",None,"towards vs to","To = the destination (go to Delhi). Towards = in the direction of (walk towards Delhi)."),
("PRP-041",Q,"'Under' takes its object directly; 'of' is not needed.","UNDER = below, often covered.","'Under construction', 'under pressure', 'under 18'.","Write a sentence about something under your bed.",None,"under vs below","Under = directly beneath, often covered. Below = at a lower level."),
("PRP-042",Q,"'Underneath' takes its object directly; 'of' is not needed.","UNDER + NEATH: directly below.","'Underneath it all' = in reality, despite appearances.","Write a sentence about something hidden underneath a table.",None,"underneath vs under","Same meaning. Underneath stresses being hidden or covered."),
("PRP-043",Q,"'Up' takes its object directly; 'of' is not needed.","UP = to a higher place.","'Up to you' = your decision.","Write a sentence about climbing up a hill.",None,"up vs above","Up = movement to a higher place. Above = position higher than."),
("PRP-044",Q,"In everyday speech, 'on' is far more natural than 'upon', and 'the' is needed.","UPON = ON, but old and formal.","'Once upon a time' starts fairy tales.","Write a sentence using 'once upon a time'.",None,"upon vs on","Same meaning. Upon is formal or literary."),
("PRP-045",Q,"'With' already shows the tool, so 'help' is extra.","WITH = together, or using.","'With' + tool: 'cut with a knife', 'write with a pen'.","Write a sentence about something you do with your hands.",None,"with vs by","With + a tool (with a knife). By + a method (by hand, by car)."),
("PRP-046",Q,"Don't combine 'in' and 'within'; choose one.","WITH + IN: inside a limit.","'Within 24 hours' = before 24 hours pass.","Write a sentence about something you must do within a week.",None,"within vs in","In an hour = after an hour. Within an hour = before an hour is over."),
("PRP-047",Q,"'Without' is followed by -ing, not 'to + verb'.","WITH + OUT: not having.","'Without doubt' = certainly.","Write a sentence about something you can't live without.",None,"without vs unless","Without + noun/-ing (without help). Unless + clause (unless you help)."),
("PRP-048",Q,"The fixed phrase uses 'to', not 'with'.","ACCORDING TO = as said by.","Don't use 'according to me'; say 'in my opinion'.","Write a sentence starting 'According to the news,…'.",None,"according to vs in my opinion","According to = someone else's view (according to the report). For yourself, use 'in my opinion'."),
("PRP-049",Q,"'Because of' + noun; 'because' + clause.","BECAUSE OF + thing. BECAUSE + sentence.","'Thanks to' = because of (for good results).","Write one sentence with 'because' and one with 'because of'.",None,"because vs because of","Because + subject + verb (because it rained). Because of + noun (because of the rain)."),
("PRP-050",Q,"There's no 'the' between 'in' and 'front'.","IN FRONT OF: three words, no 'the'.","'In the front of' = inside the front part: 'in the front of the car'.","Write a sentence about what is in front of your house.",None,"in front of vs opposite","In front of = before, facing the same way. Opposite = facing, on the other side."),
("PRP-051",Q,"'Instead of' is followed by -ing, not the base verb.","INSTEAD OF = in the place of.","'Instead' alone ends a sentence: 'We walked instead.'","Write a sentence about something you did instead of watching TV.",None,"instead of vs rather than","Similar. Instead of = replacing one thing. Rather than = preferring one thing."),
("PRP-052",Q,"The fixed phrase uses 'to', not 'of'.","NEXT TO = beside.","'Next to nothing' = almost nothing.","Write a sentence about who sits next to you.",None,"next to vs near","Next to = right beside. Near = close, but maybe not touching."),
("PRP-053",Q,"Use 'out of', not 'out from'.","OUT OF: always two words together.","'Out of the blue' = unexpectedly.","Write a sentence using 'out of the blue'.",None,"out of vs from","Out of = from inside (get out of the car). From = starting point (from Delhi)."),
("PRP-054",Q,"'Due to' + noun, not a full clause.","DUE TO + noun (due to the rain).","'Due to' is common in formal notices: 'due to technical reasons'.","Write a sentence about something delayed due to weather.",None,"due to vs because of","Similar. Due to often follows 'be': 'The delay was due to rain.'"),
("PRP-055",Q,"Never drop 'of' in 'in spite of'.","IN SPITE OF = three words, always.","'Despite' needs no 'of'; 'in spite of' always does.","Write a sentence starting 'In spite of the…'.",None,"in spite of vs despite","Same meaning. In spite of (with 'of'). Despite (without 'of')."),
("PRP-056",Q,"The fixed phrase uses 'on', not 'in'.","ON BEHALF OF = in place of, representing.","'On behalf of the team, thank you' is common in speeches.","Write a sentence speaking on behalf of your class.",None,"on behalf of vs for","On behalf of = representing someone. For = for someone's benefit."),
("PRP-057",Q,"'Prior to' is followed by -ing or a noun.","PRIOR = before (like PRIORity comes first).","'Prior to' is formal; 'before' is everyday.","Write a formal sentence using 'prior to'.",None,"prior to vs before","Same meaning. Prior to is formal."),
("PRP-058",Q,"The fixed phrase is 'close to'.","CLOSE TO = near.","'Close to' also means almost: 'close to ₹1,000'.","Write a sentence about something close to your home.",None,"close to vs near","Same meaning. Close to can also mean emotionally close."),
("PRP-059",Q,"Use 'far from', not 'far of'.","FAR FROM = a long distance from.","'Far from perfect' = not perfect at all.","Write a sentence about a place far from your city.",None,"far from vs away from","Far from = a long distance. Away from = not at, any distance."),
("PRP-060",Q,"Use 'along with', not 'along of'.","ALONG WITH = together with.","'Along with' adds something: 'The phone comes along with a charger.'","Write a sentence about something that came along with a purchase.",None,"along with vs with","Same meaning. Along with stresses 'in addition'."),
("PRP-061",Q,"The phrase is 'apart from', not 'apart of'.","APART FROM = except for, or in addition to.","'Apart from that' = except for that / also.","Write a sentence starting 'Apart from English,…'.",None,"apart from vs except","Apart from = except for, OR in addition to. Except = only 'not including'."),
("PRP-062",Q,"'Regardless' needs 'of' before the noun.","REGARDLESS OF = without caring about.","'Irregardless' is not standard English.","Write a sentence starting 'Regardless of the price,…'.",None,"regardless of vs despite","Similar. Regardless of = not affected by. Despite = even though something is true."),
("PRP-063",Q,"After 'In addition to that', don't add 'but'.","IN ADDITION TO = plus.","'In addition to' + noun or -ing.","Write a sentence starting 'In addition to my job,…'.",None,"in addition to vs besides","Same meaning. Besides is more informal."),
("PRP-064",Q,"'In case of' takes a noun; 'in case' takes a clause.","IN CASE OF + noun (in case of fire). IN CASE + clause (in case it rains).","'In case of emergency' is a common sign.","Write a sentence using 'in case of'.",None,"in case of vs in case","In case of + noun. In case + subject + verb."),
("PRP-065",Q,"'Means' keeps its -s even for one method.","BY MEANS OF = using.","'By all means' = certainly, please do.","Write a formal sentence using 'by means of'.",None,"by means of vs with","By means of = formal 'using'. With = everyday 'using' a tool."),
("PRP-066",Q,"In everyday speech, use 'on top of', not 'on the top of'.","ON TOP OF = on the highest part.","'On top of that' = also, in addition (often bad things).","Write a sentence starting 'On top of that,…'.",None,"on top of vs above","On top of = touching the top. Above = higher, not touching."),
("PRP-067",Q,"'On account of' takes a noun, not a clause.","ON ACCOUNT OF = because of (formal).","Common in formal notices: 'on account of bad weather'.","Write a formal sentence using 'on account of'.",None,"on account of vs because","On account of + noun. Because + clause."),
("PRP-068",Q,"'For the sake of' takes a noun, not a clause.","FOR THE SAKE OF = for the benefit of.","'For heaven's sake!' expresses annoyance.","Write a sentence about something you did for the sake of your family.",None,"for the sake of vs for","For the sake of = to help or protect. For is more general."),
("PRP-069",Q,"The phrase uses singular 'regard': 'with regard to'.","REGARD (singular) in 'with regard to'. REGARDS (plural) ends emails.","'Regards' at an email's end = best wishes.","Write an email line starting 'With regard to your…'.",None,"with regard to vs with regards","With regard to = about (formal). 'Regards' = a greeting at the end of an email."),
("PRP-070",Q,"The fixed phrase uses 'to', not 'with'.","IN RELATION TO = connected with.","Common in formal and academic writing.","Write a formal sentence using 'in relation to'.",None,"in relation to vs about","Same idea. In relation to is formal; about is everyday."),
("CNJ-001",C,"With just two items joined by 'and', no commas are needed.","AND = plus.","'And' at the start of a sentence is fine in speech and informal writing.","Write a sentence joining three things with 'and'.",None,"and vs also","And joins words or clauses. Also adds information inside a clause: 'I also like tea.'"),
("CNJ-002",C,"Don't use 'although' and 'but' in one sentence. Pick one.","BUT = contrast. Hindi 'haalaanki… lekin' uses both, but English uses only one.","'But' is the most common contrast word in English.","Write a sentence using 'but' to show contrast.",None,"but vs although","But joins two clauses (It rained, but we went). Although starts a clause (Although it rained, we went)."),
("CNJ-003",C,"For a choice between options, use 'or', not 'and'.","OR = choose one.","'Or else' = otherwise (a warning).","Write a question offering a choice with 'or'.",None,"or vs and","Or = one of the options. And = both together."),
("CNJ-004",C,"After 'nor', put the auxiliary before the subject: 'nor does she smoke'.","NOR = and not. NEITHER…NOR.","'Nor' is formal; 'and doesn't … either' is everyday.","Write a sentence with 'neither … nor'.",None,"nor vs or","Nor = and not (negative). Or = choice (positive)."),
("CNJ-005",C,"Don't use 'because' and 'so' together. Pick one.","SO = result. BECAUSE = reason. One per sentence.","'So' is also used to start a story: 'So, yesterday…'.","Write a sentence using 'so' to show a result.",None,"so vs because","Because = reason (I left because it was late). So = result (It was late, so I left)."),
("CNJ-006",C,"With the present perfect in negatives, use 'yet', not 'till now'.","YET = up to now (not yet). Also: 'but' (young, yet talented).","'Not yet' = not so far, but expected.","Write a sentence using 'not … yet'.",None,"yet vs still","Yet = in negatives and questions (not yet). Still = continuing (still waiting).","He has not come till now.","He has not come yet."),
("CNJ-007",C,"Never use 'but' with 'although'.","ALTHOUGH… (no BUT). One contrast word only.","'Although' can start or be in the middle of a sentence.","Write a sentence starting 'Although…'.",None,"although vs though","Same meaning. Though is more informal and can end a sentence: 'It was good, though.'"),
("CNJ-008",C,"Don't use 'though' and 'but' together.","THOUGH = although, informal.","At the end of a sentence, 'though' = however: 'It's expensive. Good, though.'","Write a sentence ending with ', though.'",None,"though vs through","Though (/ðəʊ/) = although. Through (/θruː/) = from one side to the other.","Though he is rich, but he is humble.","Though he is rich, he is humble."),
("CNJ-009",C,"'Even though' already shows contrast, so drop 'but'.","EVEN THOUGH = stronger ALTHOUGH.","Use 'even though' for real facts; 'even if' for possible situations.","Write a sentence starting 'Even though…'.",None,"even though vs even if","Even though = it's true (even though it's raining). Even if = it might be true (even if it rains)."),
("CNJ-010",C,"Don't use 'because' and 'so' together.","BECAUSE = the reason why.","'Because' alone as an answer is informal: 'Why? — Because.'","Write a sentence starting 'Because…'.",None,"because vs since","Same for reasons. Since is more formal and also means 'from a time'."),
]
